const item=$input.first();
const d=item.json;
const fall=String(d.obd2_testfall??'p0300').trim().toLowerCase();
const allowed=['ohne_fehler','p0300','p0420','verbindungsfehler'];
if(!allowed.includes(fall)) throw new Error('Ungültiger obd2_testfall. Erlaubt: '+allowed.join(', '));
const zeit=new Date().toISOString();
const messwert=(name,wert,einheit)=>({name,wert,einheit,quelle:'OBD2-Simulator',simuliert:true});
const katalog={
 p0300:{codes:['P0300'],beschreibung:'Zufällige oder mehrfache Verbrennungsaussetzer; keine bestätigte Fehlerursache.',drehzahl:820,kuehlmittel:90,spannung:13.9},
 p0420:{codes:['P0420'],beschreibung:'Katalysatorwirkung unter dem Grenzwert (Bank 1); keine bestätigte Fehlerursache.',drehzahl:780,kuehlmittel:92,spannung:14.1},
 ohne_fehler:{codes:[],beschreibung:'Simulierter Fehlerspeicher enthält keine Codes. Das beweist keinen fehlerfreien Fahrzeugzustand.',drehzahl:800,kuehlmittel:88,spannung:14.0}
};
let obd2;
if(fall==='verbindungsfehler') {
 obd2={simuliert:true,datenquelle:'OBD2-Simulator',testfall:fall,zeitstempel:zeit,verbindungsstatus:'FEHLER',auslesestatus:'KEINE_DATEN',fehlercodes:null,code_details:null,messwerte:null,fehler:{code:'ADAPTER_NICHT_ERREICHBAR',nachricht:'Simulierter Adapter ist nicht erreichbar. Es wurden keine Fahrzeugdaten gelesen.'}};
} else {
 const v=katalog[fall];
 obd2={simuliert:true,datenquelle:'OBD2-Simulator',testfall:fall,zeitstempel:zeit,verbindungsstatus:'VERBUNDEN_SIMULIERT',auslesestatus:'ERFOLGREICH_SIMULIERT',fehlercodes:v.codes,code_details:v.codes.map(code=>({code,bedeutung:v.beschreibung,quelle:'Lokaler Demo-Katalog'})),messwerte:[messwert('Motordrehzahl',v.drehzahl,'U/min'),messwert('Kühlmitteltemperatur',v.kuehlmittel,'°C'),messwert('Bordspannung',v.spannung,'V')],fehler:null};
}
// Alle Eingangsdaten erhalten; Kundenangaben nicht mit Simulatorwerten überschreiben.
return [{json:{
 ...d,
 obd2,
 obd2_status:obd2.auslesestatus,
 obd2_simulation:true,
 obd2_hinweis:'SIMULATION – keine Messung am echten Fahrzeug. Messwerte und Fehlercodes sind Beispieldaten. Keine Diagnose oder Fahrfreigabe.',
 obd2_naechster_schritt:fall==='verbindungsfehler'?'ADAPTERVERBINDUNG_PRUEFEN':'SIMULATIONSDATEN_FUER_BERICHT_VERWENDEN'
},binary:item.binary??{}}];
